WITH enriched AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY shipping_fee, id) AS event_seq, PERCENT_RANK() OVER (PARTITION BY store_id ORDER BY discount DESC NULLS LAST) AS discount_percent_rank FROM orders) SELECT CASE WHEN discount_percent_rank >= 0.64 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_percent_rank_tier, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, COUNT(DISTINCT store_id) AS distinct_store_ids, SUM(CASE WHEN channel = 'mobile' THEN amount ELSE 0 END) AS mobile_amount FROM enriched GROUP BY discount_percent_rank_tier HAVING distinct_store_ids < 1;
